mapper.insert:
insert into cere_sku_member_real_info
(
sku_id, product_id, member_level_id, activity_type, activity_id,
cur_price, cur_original_price, min_price, max_price, limit_number,
if_enable, enable_time, if_add, person, sales_user_count,
sales_volume, sku_sales_volume, product_sales_volume, start_time, end_time,
state, create_time, update_time
)
values (
#{skuId}, #{productId}, #{memberLevelId}, #{activityType}, #{activityId},
#{curPrice}, #{curOriginalPrice}, #{minPrice}, #{maxPrice}, #{limitNumber},
#{ifEnable}, #{enableTime}, #{ifAdd}, #{person}, #{salesUserCount},
#{salesVolume}, #{skuSalesVolume}, #{productSalesVolume}, #{startTime}, #{endTime},
#{state}, #{createTime}, #{updateTime}
)
on duplicate key update
update_time = #{updateTime}

    ,activity_type = #{activityType}


    ,activity_id = #{activityId}


    ,cur_price = #{curPrice}


    ,cur_original_price = #{curOriginalPrice}


    ,min_price = #{minPrice}


    ,max_price = #{maxPrice}


    ,limit_number = #{limitNumber}


    ,if_enable = #{ifEnable}


    ,enable_time = #{enableTime}


    ,if_add = #{ifAdd}


    ,person = #{person}


    ,sales_user_count = #{salesUserCount}


    ,sales_volume = #{salesVolume}


    ,sku_sales_volume = #{skuSalesVolume}


    ,product_sales_volume = #{productSalesVolume}


    ,start_time = #{startTime}


    ,end_time = #{endTime}


    ,state = #{state}

mapper.delete:
delete from cere_sku_member_real_info
where product_id in

    #{productId}

mapper.update:
update cere_sku_member_real_info
set sales_volume = sales_volume + #{addedNumber},
sku_sales_volume = sku_sales_volume + #{addedNumber},
product_sales_volume = product_sales_volume + #{addedNumber}
where product_id = #{productId}

update cere_sku_member_real_info
set sales_user_count = sales_user_count + 1
where product_id in
(

    #{productId}

)

mapper.select:
select a.shop_id, a.product_id, a.product_name, a.product_text text, a.shelve_state, a.if_huabei, a.product_brief, a.classify_id, a.if_logistics,
b.sku_id, b.cur_price as price, b.cur_original_price as original_price, b.cur_original_price as sale_price, b.sales_user_count as users, b.product_sales_volume as number, b.activity_type, b.activity_id, b.start_time, b.end_time, b.if_enable - 1 as ifEnable, b.if_add, b.person,
if(b.activity_type = 4, b.activity_id, 0) as platform_seckill_id, if(b.activity_type = 5, b.activity_id, 0) as platform_discount_id, if(b.activity_type = 2, b.activity_id, 0) as shop_seckill_id, if(b.activity_type = 3, b.activity_id, 0) as shop_discount_id, if(b.activity_type = 1, b.activity_id, 0) as shop_group_work_id, if(b.activity_type = 8, b.activity_id, 0) as scene_id,
c.shop_name, c.shop_logo,
cps.weight, cps.stock_number as surplus_number, cps.total from cere_shop_product a join cere_sku_member_real_info b on b.product_id = a.product_id join cere_platform_shop c on c.shop_id = #{shopId} join cere_product_sku cps on cps.sku_id = #{skuId} where b.sku_id = #{skuId}
and a.shop_id = #{shopId}
and b.member_level_id = #{memberLevelId}

select ANY_VALUE(b.sku_id) as sku_id, b.product_id, ANY_VALUE(b.cur_price) as price, ANY_VALUE(b.cur_original_price) as original_price, ANY_VALUE(b.activity_type) as activity_type, ANY_VALUE(b.product_sales_volume + ifnull(csp.fictitious_number,0)) as number, ANY_VALUE(b.limit_number) as total, ANY_VALUE(b.sales_user_count) as users, ANY_VALUE(csp.product_name) as product_name, ANY_VALUE(csp.product_brief) as product_brief, ANY_VALUE(shop.shop_id) as shop_id, ANY_VALUE(shop.shop_name) as shop_name, ANY_VALUE(shop.shop_logo) as shop_logo, ANY_VALUE(cpi.product_image) as image, ANY_VALUE(b.sku_sales_volume) as sku_sales_volume, ANY_VALUE(csp.update_time) as update_time, ANY_VALUE(csp.create_time) as create_time
from cere_sku_member_real_info b join cere_shop_product csp on csp.product_id = b.product_id join cere_product_sku cps on cps.sku_id = b.sku_id join cere_platform_shop shop on shop.shop_id = csp.shop_id left join cere_product_image cpi on cpi.product_id = b.product_id left join cere_product_classify cpc on cpc.classify_id = csp.classify_id
b.member_level_id = #{memberLevelId} and csp.shelve_state = 1
and shop.shop_id = #{shopId}
and csp.product_name like concat('%', #{search}, '%')
and csp.classify_id1 = #{classifyId}
and csp.classify_id2 = #{classifyId}
and csp.classify_id3 = #{classifyId}
and ( csp.classify_id1 = #{classifyId} OR csp.classify_id2 = #{classifyId} OR csp.classify_id3 = #{classifyId} )
and b.cur_price >= #{minMoney}
and b.cur_price <= #{maxMoney}
and csp.shop_group_id = #{groupId}
group by b.product_id ORDER BY
price,
price desc,
sku_sales_volume,
sku_sales_volume DESC,
update_time DESC, create_time DESC

select
b.sku_id,
b.cur_price as price,
b.cur_original_price as original_price,

b.cur_original_price as sale_price,
b.activity_type,
b.activity_id,
b.start_time,
b.end_time,
b.if_enable - 1 as ifEnable,
b.person,

cps.stock_number,
b.limit_number,

if(b.activity_type = 4, b.activity_id, 0) as platform_seckill_id,
if(b.activity_type = 5, b.activity_id, 0) as platform_discount_id,
if(b.activity_type = 2, b.activity_id, 0) as shop_seckill_id,
if(b.activity_type = 3, b.activity_id, 0) as shop_discount_id,
if(b.activity_type = 1, b.activity_id, 0) as shop_group_work_id,
if(b.activity_type = 8, b.activity_id, 0) as scene_id

from cere_sku_member_real_info b
join cere_product_sku cps on cps.sku_id = b.sku_id
where b.member_level_id = #{memberLevelId}
and b.sku_id in
(

    #{skuId}

)

select
*
from cere_sku_member_real_info
where sku_id = #{skuId}
and member_level_id = #{memberLevelId}

select b.sku_id, b.product_id, b.cur_price as price, b.cur_original_price as original_price,
b.cur_original_price as sale_price, b.activity_type, b.activity_id, b.start_time, b.end_time, b.if_enable - 1 as ifEnable, b.person,
cps.stock_number, cps.total,
if(b.activity_type = 4, b.activity_id, 0) as platform_seckill_id, if(b.activity_type = 5, b.activity_id, 0) as platform_discount_id, if(b.activity_type = 2, b.activity_id, 0) as shop_seckill_id, if(b.activity_type = 3, b.activity_id, 0) as shop_discount_id, if(b.activity_type = 1, b.activity_id, 0) as shop_group_work_id, if(b.activity_type = 8, b.activity_id, 0) as scene_id,
min(csn.image) as image, group_concat(csn2.value_code) valueCodes
from cere_sku_member_real_info b join cere_product_sku cps on cps.sku_id = b.sku_id left join cere_sku_name csn on csn.sku_id = b.sku_id and csn.image is not null and csn.image != '' left join cere_sku_name csn2 on csn2.sku_id = b.sku_id where b.product_id in (
#{productId}
) and b.member_level_id = #{memberLevelId} group by b.sku_id
